-- Lot 213 : payloads 361 a 390 sur 1299.
--
-- Chaque commande recoit un texte propre a ChatGPT, a Claude et a Gemini.
-- Rien n'est supprime : l'ancienne version quitte le courant et reste lisible
-- dans l'historique, ce qui suffit a revenir en arriere.

drop table if exists lot_v5_payloads;
create temporary table lot_v5_payloads as
select * from jsonb_to_recordset($raccourcia$[{"ref":"RCI-IMG-074","moteur":"chatgpt","payload":"[RaccourcIA — /silhouetteportrait]\n\nMISSION\nCréer une silhouette graphique à partir d'un portrait. Préserve profil, coiffure et posture, construis un contre-jour net et un contour lumineux. Assume la perte de détail facial propre à l’effet.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque image jointe. Si un outil de génération ou d’édition d’image est disponible, utilise-le avec les références exactes. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quel usage ou style doit guider la transformation du portrait ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Portrait silhouette » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Préserve profil, coiffure et posture, construis un contre-jour net et un contour lumineux. Assume la perte de détail facial propre à l’effet. Le format par défaut est 4:5 en haute définition; adapte-le au canal explicite. N’ajoute aucun texte sauf demande explicite.\n\nPRÉSERVER\nConserve l’identité, la structure du visage, la carnation, l’âge apparent et les proportions corporelles, sauf changement explicitement demandé.\n\nÉVITER\nÉvite visage remplacé, peau lissée artificiellement, morphologie modifiée, doigts incorrects, pose impossible et changement ethnique. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Sujet reconnaissable; effet visible; cohérence de perspective, lumière, matière et ombres; aucun artefact majeur; texte absent ou lisible. Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique en une phrase que l’image n’a pas été générée.","sha256":"eabaf89c7405b7e5b5920feb28790a533cb501e0bbd481ded5d356b81bcde10f"},{"ref":"RCI-IMG-074","moteur":"claude","payload":"[RaccourcIA — /silhouetteportrait]\n\nMISSION\nCréer une silhouette graphique à partir d'un portrait. Préserve profil, coiffure et posture, construis un contre-jour net et un contour lumineux. Assume la perte de détail facial propre à l’effet.\n\nDÉCISION\nRepère d’abord les contraintes dans les images et documents, puis consolide-les sans longue reformulation. Vérifie les capacités réellement disponibles avant toute production. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quel usage ou style doit guider la transformation du portrait ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Portrait silhouette » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Préserve profil, coiffure et posture, construis un contre-jour net et un contour lumineux. Assume la perte de détail facial propre à l’effet. Le format par défaut est 4:5 en haute définition; adapte-le au canal explicite. N’ajoute aucun texte sauf demande explicite.\n\nPRÉSERVER\nConserve l’identité, la structure du visage, la carnation, l’âge apparent et les proportions corporelles, sauf changement explicitement demandé.\n\nÉVITER\nÉvite visage remplacé, peau lissée artificiellement, morphologie modifiée, doigts incorrects, pose impossible et changement ethnique. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Sujet reconnaissable; effet visible; cohérence de perspective, lumière, matière et ombres; aucun artefact majeur; texte absent ou lisible. Sans moteur image connecté, livre un brief de transfert autonome, précis et exploitable. Ne prétends jamais avoir rendu ou inspecté une image inexistante.","sha256":"fb36c1e05ddabd089ce25c70cfe5e9125fc35ae226ea17f3427f5b3e89719776"},{"ref":"RCI-IMG-074","moteur":"gemini","payload":"[RaccourcIA — /silhouetteportrait]\n\nMISSION\nCréer une silhouette graphique à partir d'un portrait. Préserve profil, coiffure et posture, construis un contre-jour net et un contour lumineux. Assume la perte de détail facial propre à l’effet.\n\nDÉCISION\nInspecte visuellement toutes les pièces jointes avant le texte de contexte. Relie clairement chaque référence à son rôle : sujet, style, marque, données ou composition. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quel usage ou style doit guider la transformation du portrait ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloq